export function listEnterpriseKpis(filters = {}) {
    return ENTERPRISE_KPI_REGISTRY.filter((kpi) => {
        if (filters.domain && kpi.domain !== filters.domain)
            return false;
        if (filters.lifecycle && kpi.lifecycle !== filters.lifecycle)
            return false;
        if (filters.sourceAvailability &&
            kpi.source.availability !== filters.sourceAvailability) {
            return false;
        }
        return true;
    });
}
export function getEnterpriseKpi(id) {
    return ENTERPRISE_KPI_REGISTRY.find((kpi) => kpi.id === id) ?? null;
}
export function validateEnterpriseKpiRegistry() {
    const ids = new Set();
    const issues = [];
    for (const definition of ENTERPRISE_KPI_REGISTRY) {
        if (!/^KPI-(PLAT|SRCH|CUST|OPS|BUS|GROW|GOV)-\d{3}$/.test(definition.id)) {
            issues.push(`${definition.id}: invalid identifier`);
        }
        if (ids.has(definition.id))
            issues.push(`${definition.id}: duplicate id`);
        ids.add(definition.id);
        const required = [
            definition.name,
            definition.description,
            definition.businessPurpose,
            definition.executiveOwnerRole,
            definition.formula,
            definition.source.definition,
            definition.updateFrequency,
            definition.governanceNotes,
        ];
        if (required.some((value) => value.trim().length === 0)) {
            issues.push(`${definition.id}: missing required text field`);
        }
    }
    return { valid: issues.length === 0, issues };
}
